.nitro-room-thumbnail-camera {
    width: 132px;
    height: 192px;
    background-image: url('@/assets/images/room-widgets/thumbnail-widget/thumbnail-camera-spritesheet.png');

    .camera-frame {
        position: absolute;
        width: 110px;
        height: 110px;
        margin-top: 30px;
        margin-left: 3px;
    }
}

.nitro-layout-trophy {
    position: relative;
    width: 340px;
    height: 173px;
    color: black;
    pointer-events: all;

    background-position: 0px 0px;
    background-image: url('@/assets/images/room-widgets/trophy-widget/trophy-spritesheet.png');

    &.trophy-2 {
        background-position: 0px 173px;
    }

    &.trophy-3 {
        background-position: 0px 346px;
    }

    .trophy-header {
        height: 22px;

        .trophy-close {
            width: 15px;
            height: 15px;
            right: 5.5px;
            top: 5px;
        }
    }

    .trophy-content {
        width: 297px;
        height: 116px;
        white-space: pre-wrap;
        word-break: break-word;
        overflow: auto;
    }

    .trophy-footer {
        width: 297px;
    }
}

.nitro-gift-card {
    width: 306px;
    height: 159px;
    background: url('@/assets/images/gift/gift_tag.png') center no-repeat;

    .gift-face {
        width: 65px;

        .gift-incognito {
            width: 37px;
            height: 48px;
            background: url('@/assets/images/gift/incognito.png') center no-repeat;
        }

        .gift-avatar {
            position: relative;
            overflow: hidden;
            width: 40px;
            height: 50px;

            .avatar-image {
                position: absolute;
                left: -25px;
                top: -20px;
            }
        }
    }

    .gift-message {
        width: 100%;
        min-width: 100%;
        max-width: 100%;
        border: none;
        resize: none;
        outline: none;
        line-height: 17px;
    }
}

.spinner-container {
    display: flex;
    align-items: center;
    justify-content: center;

    .spinner {
        margin: 2px;
        width: 10px;
        height: 10px;
        border: $border-width solid $white;
        background-color: rgba($white, 0.8);
        border-radius: 100%;
        display: inline-block;
        -webkit-animation: sk-bouncedelay 1.4s infinite ease-in-out both;
        animation: sk-bouncedelay 1.4s infinite ease-in-out both;

        &:nth-child(1) {
            -webkit-animation-delay: -0.32s;
            animation-delay: -0.32s;
        }

        &:nth-child(2) {
            -webkit-animation-delay: -0.16s;
            animation-delay: -0.16s;
        }
    }
}

@-webkit-keyframes sk-bouncedelay {

    0%,
    80%,
    100% {
        -webkit-transform: scale(0);
    }

    40% {
        -webkit-transform: scale(1);
    }
}

@keyframes sk-bouncedelay {

    0%,
    80%,
    100% {
        -webkit-transform: scale(0);
        transform: scale(0);
    }

    40% {
        -webkit-transform: scale(1);
        transform: scale(1);
    }
}

.room-thumbnail {
    position: relative;
    width: 110px;
    height: 110px;
    background: url('@/assets/images/navigator/thumbnail_placeholder.png') no-repeat center;
    background-color: rgba($black, 0.125);
}

#draggable-windows-container {
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    pointer-events: none;
    overflow: hidden;

    @include media-breakpoint-down(lg) {
        display: flex;
        justify-content: center;
        align-items: center;
    }

    .draggable-window {
        display: inline-block;
        visibility: hidden;
        pointer-events: all;
    }
}

.nitro-currency-icon {
    background-position: center;
    background-repeat: no-repeat;
    width: 16px;
    height: 16px;
}

.nitro-item-count {
    top: 2px;
    right: 2px;
    font-size: 9.5px;
    padding: 2px 3px;
    z-index: 1;
}

.badge-image {
    position: relative;
    width: 40px;
    height: 40px;
    background-repeat: no-repeat;
    background-position: center;

    .badge-information {
        display: none;
    }

    &:hover {
        .badge-information {
            display: block;
        }
    }

    .badge-information {
        position: absolute;
        pointer-events: none;
        user-select: none;
        width: 210px;
        border-radius: $border-radius;
        background: $white;
        left: -220px;
        z-index: 100;

        &:before {
            position: absolute;
            content: ' ';
            width: 0;
            height: 0;
            border-left: 10px solid $white;
            border-bottom: 10px solid transparent;
            border-top: 10px solid transparent;
            top: 10px;
            right: -10px;
        }
    }
}

.furni-image {
    position: relative;
    width: 100%;
    height: 100%;
    background-repeat: no-repeat;
    background-position: center;
}

