.avatar-image {
    position: relative;
    width: 90px;
    height: 130px;
    background-repeat: no-repeat;
    background-position: center -8px;
    pointer-events: none;
}

.avatar-banner {
    position: relative;
    width: 67px;
    height: 130px;
    background-repeat: no-repeat;
    border-radius: 6px;
    overflow: hidden;
    pointer-events: none;

    .avatar-image {
        position: absolute;
        max-width: 67px;
    }
}

.banner-image {
    position: absolute;
    width: 67px;
    height: 130px;
}

.pet-image {
    position: relative;
    width: 100%;
    height: 100%;
    background-repeat: no-repeat;
    background-position: center;
