.border
{
    border: 1px solid #29292b !important;
}

.room-preview-container {
    position: relative;
    width: 100%;

    .room-preview-image {
        position: relative;
        top: 0;
        left: 0;
        height: 100%;
        width: 100%;
        border-radius: $border-radius;
        background-color: $light;
        background-repeat: no-repeat;
        background-position: center;
        overflow: hidden;

        &.border-0 {
            &::after {
                content: none;
            }
        }

        &::after {
            position: absolute;
            content: '';
            top: 0;
            bottom: 0;
            left: 0;
            right: 0;
            border-radius: $border-radius;
            border-bottom: 2px solid white;
            border-right: 2px solid white;
            box-shadow: -2px -2px rgba(0, 0, 0, 0.4),
                inset 3px 3px rgba(0, 0, 0, 0.2);
        }
    }
}

.unique-item {
    .unique-bg-override {
        background-position: center;
        background-repeat: no-repeat;
        z-index: 2;
    }

    &:before {
        position: absolute;
        content: '';
        width: 100%;
        height: 100%;
        background: url('@/assets/images/unique/grid-bg.png') center no-repeat;
        z-index: 1;
    }

    &:after {
        position: absolute;
        content: '';
        width: 100%;
        height: 100%;
        background: url('@/assets/images/unique/grid-bg-glass.png') center no-repeat;
        bottom: 0;
        z-index: 4;
    }

    &.sold-out:after {
        background: url('@/assets/images/unique/grid-bg-sold-out.png') center no-repeat,
            url('@/assets/images/unique/grid-bg-glass.png') center no-repeat;
    }

    .unique-item-counter {
        margin: 0 auto;
        display: flex;
        justify-content: center;
        align-items: center;
        bottom: 1px;
        width: 100%;
        height: 9px;
        background: url('@/assets/images/unique/grid-count-bg.png') center no-repeat;
        z-index: 3;
    }
}

.unique-sold-out-blocker {
    width: 364px;
    height: 30px;
